INSERT INTO `tmp_default_rows` VALUES (3,'registration','Registration','Dear {name}\r\n<pre>\r\n<code>Your account has been successfully created.\r\n\r\nPlease click {link}\r\n</code>Your Login Email is: {email}\r\nYour Login Pawword is: {password}\r\nNote:Kindly change your Password on First Login for security Purpose.\r\n\r\nYou can also download the mobile app from {applink}\r\n\r\n\r\n\r\n</pre>\r\nKind Regards<br />\r\n{email_signature}','2025-04-29 11:56:23',2,2,'2025-04-29 11:56:23'),(4,'password_change','Password','Dear {name}<br />\r\nPlease Click here to reset your password {link}<br />\r\n<br />\r\nKind Regards<br />\r\n{email_signature}','2024-04-19 11:00:21',2,2,'2024-04-19 11:00:21'),(5,'registration','Registration','Dear {name}\r\n<pre>\r\n<code>Your account has been successfully created.\r\n\r\nPlease click {link}\r\n</code>Your Login Email is: {email}\r\nYour Login Pawword is: {password}\r\nNote:Kindly change your Password on First Login for security Purpose.\r\n\r\nYou can also download the mobile app from {applink}\r\n\r\n\r\n\r\n</pre>\r\nKind Regards<br />\r\n{email_signature}','2025-04-29 11:56:23',2,2,'2025-04-29 11:56:23'),(6,'renewed','Renewed','Dear {name}<br />\r\n<br />\r\nYour subscription account has been renewed successfully.<br />\r\n<br />\r\nKind Regards<br />\r\n{email_signature}','2024-07-10 12:50:21',2,2,'2024-07-10 12:50:21'),(7,'subscribed','subscibed','Dear {name}<br />\r\n<br />\r\nYour have successfully subscribed Saral OMS . You can now start using the system.<br />\r\n<br />\r\nKind Regards<br />\r\n{email_signature}','2025-01-31 10:56:10',1,1,'2025-01-31 10:56:10'),(8,'expired','Expired','Dear {name}<br />\r\n<br />\r\nYour subscription account has been expired. Please contact our office for renewing the account.<br />\r\n<br />\r\nKind Regards<br />\r\n{email_signature}','2024-07-10 12:53:12',2,2,'2024-07-10 12:53:12'),(9,'going_expired','going expired','Dear {name}<br />\r\n<br />\r\nYour subscription account is going to expire. Please renew at the earliest.<br />\r\n<br />\r\nKind Regards<br />\r\n{email_signature}','2024-07-10 12:52:14',2,2,'2024-07-10 12:52:14'),(10,'late_arrive','Punctuality Concern – Formal Warning','Dear Team Member,<br />\r\nThis email serves as a formal warning regarding your punctuality conern.&nbsp;As per our company policy on punctuality, employees are expected to arrive on time for their scheduled shifts<br />\r\nAs per system you have arrived on {time}.<br />\r\nthat continued lateness will be treated as a disciplinary concern and will also affect your salary calculation.<br />\r\nWe value your contribution to the company and hope to see an immediate improvement in your punctuality.<br />\r\n<strong>Sincerely,<br />\r\nHuman Resource Department</strong>','2025-06-18 10:54:40',1020,1020,'2025-06-18 10:54:40'),(11,'lead_quotation_send','Quotation {number} from {company_name}','<p>Dear {contact_name},</p><p>Thank you for your enquiry about {lead_title}. Please find our quotation {number} attached, valid until {valid_until}.</p><p>{link}</p><p>Regards,<br>{sender_name}<br>{company_name}</p>','2026-09-29 14:55:37',0,NULL,NULL),(12,'lead_proposal_send','Proposal {number} from {company_name}','<p>Dear {contact_name},</p><p>Please find our proposal {number} for {lead_title} attached.</p><p>{link}</p><p>Regards,<br>{sender_name}<br>{company_name}</p>','2026-09-29 14:55:37',0,NULL,NULL);
