  `opening_accumulated_dep` double(30,4) NOT NULL DEFAULT '0.0000' COMMENT 'Depreciation already taken before this system, for an opening import',
  `capitalisation_voucher_id` int(11) DEFAULT NULL,
  `status` enum('in_store','issued','under_repair','disposed','lost') NOT NULL DEFAULT 'in_store',
  `godown_id` int(11) DEFAULT NULL,
